# -*- coding: utf-8 -*-
from pathlib import Path
import subprocess
import yaml

p=Path('projects/stezhok')
f=p/'state/ledger/experiments.yaml'
rows=yaml.safe_load(f.read_text())
rows[0]['stop_go'] += ' Уточнение после синтетического отказа C3 в рамках CHG-001: exit 2 по неполным полям и отсутствие нового файла — не успешная карточка и не доказательство бесполезности аудита. Удержать строку; сохранить исходный вход, код и stderr; в копии заполнить только отсутствующие/пустые promise/source/scope/missing по проверенному материалу, не менять уже заполненные поля и не выдумывать основания; затем планировать повтор той же команды на копии с новым выходным путём только в оставшемся общем лимите труда HYP-004, включая диагностику и исправление. Повтор считается выполненным лишь при отдельном зафиксированном запуске, коде 0 и новом файле с соответствием карточке; наличие прежнего файла не успех. Если основания для пропуска неизвестны, не хватает оставшегося лимита, повтор снова отвергнут, ошибка иная или результат неясен — удержать строку, перечислить дефицит и обратиться к инициатору; не расширять лимит и не засчитывать go. Это предложенная процедура после C3, не запись исполнения EXP.'
rows[0]['status_note'] += ' CHG-001: после отказа версии 0bc83266a27c84660a23bcf476c12aa12f741c5f2bef07a6f26c019a482cd236 уточнена ветка технического неуспеха/восстановления. Прежний выбор, численный лимит и содержательные stop/go не заменены; схема повторного оформления не результат EXP-001. Новая версия ждёт отдельного C3.'
f.write_text(yaml.safe_dump(rows,allow_unicode=True,sort_keys=False))
subprocess.run(['.venv/bin/python','tools/ledger.py','validate',str(p)],check=True)

f=p/'outputs/05_product_strategy.md'; s=f.read_text()
needle='## Осознанные отказы\n'
block='''### Инструкция аналитику: отказ и восстановление оформления
Наблюдённый отказ неполного входа — код выхода `exit 2` и отсутствие нового файла; это не успешная карточка [CLM-008] (fact, high). Для каждого запуска заранее выбирайте новый выходной путь, чтобы не принять прежний файл за новый результат. Оформление успешно только при `exit 0`, наличии нового файла и соответствии его содержимого заполненной карточке; это всё ещё не проверка истины [CLM-008; CLM-009].
При отказе сохраните исходный вход, код и stderr. Если ошибка именно о неполных полях, сделайте копию входа и заполните только отсутствующие или пустые `promise`, `source`, `scope`, `missing` по уже проверенному материалу. Не меняйте заполненные поля и не сочиняйте источник/границу ради прохождения CLI. Неизвестный недостающий текст остаётся дефицитом, а не заполнителем [CLM-009; EXP-001] (пересмотрено по CHG-001).
Запланируйте повтор той же команды с исправленной копией и новым выходным путём только в остатке общего лимита 2 часа, включая первый отказ, диагностику, исправление и повтор [HYP-004; EXP-001]. Шаблон из корня live: `.venv/bin/python projects/stezhok/sources/lab-audit/audit.py --input <исправленная-копия.json> --output <новый-результат.md>`. До реального запуска пишите «повтор запланирован», не «выполнен» (пересмотрено по CHG-001).
Если данных для пропуска нет, остаток лимита не позволяет исправление, повтор снова отклонён, ошибка иная или нет ясного кода/нового файла — удержите результат и сообщите инициатору конкретные поля, ошибку и использованный труд. Не повышайте лимит автоматически и не засчитывайте отказ или старый файл как успешную карточку. После подтверждённого оформления вернитесь к ручной сверке и содержательным условиям EXP-001; технический успех не означает go [CLM-009; EXP-001] (пересмотрено по CHG-001).

'''
assert needle in s
s=s.replace(needle,block+needle)
f.write_text(s)

f=p/'outputs/07_validation_plan.md'; s=f.read_text()
needle='## Ранние сигналы\n'
block='''## Отказ CLI и восстановление до содержательной оценки
Эта ветка дополняет EXP-001, не вводя новый лимит или факт полезности. Неполный вход уже наблюдался как `exit 2` без нового файла [CLM-008]. Отказ не является успешной карточкой и сам по себе не доказывает отсутствие полезности [EXP-001] (пересмотрено по CHG-001).

| Наблюдение | Статус строки | Следующее действие аналитика |
|---|---|---|
| `exit 2`, ошибка неполных полей, нового файла нет | Технический отказ, не успех | Сохранить вход и stderr; в копии заполнить только отсутствующие/пустые поля по проверенному материалу; заполненные поля сохранить; повтор планировать лишь в оставшемся общем лимите труда HYP-004 [CLM-008; EXP-001] (пересмотрено по CHG-001) |
| Поля исправлены, но команда ещё не запускалась | Повтор запланирован, не выполнен | Запустить ту же команду с исправленной копией и новым выходным путём только при достаточном остатке лимита; записать реальный код/выход; до этого строка удержана [EXP-001] (пересмотрено по CHG-001) |
| Реальный повтор дал `exit 0`, новый файл соответствует исправленной карточке | Оформление выполнено, содержание ещё проверяется | Отметить технический успех отдельно, затем вручную сверить основание и перейти к содержательным stop/go; истина автоматически не проверена [CLM-008; CLM-009; EXP-001] (пересмотрено по CHG-001) |
| Есть прежний файл, но отказ/код неизвестен/новый файл не подтверждён | Успех не подтверждён | Не засчитывать старый файл, удержать строку и передать инициатору конкретную неопределённость [EXP-001] (пересмотрено по CHG-001) |
| Нет основания заполнить пропуск, остаток лимита исчерпан, ошибка иная или повтор снова отказал | Удержание, go не допускается | Сохранить дефицит, код и фактический труд, обратиться к инициатору; не придумывать текст, не расширять лимит и не продолжать цепочку повторов [HYP-004; EXP-001] (пересмотрено по CHG-001) |

В лимит 2 часа входят все попытки, диагностика, исправление и ручная сверка [HYP-004; EXP-001]. Неполная/неоформленная строка остаётся в знаменателе заданных классов CLM-006 и не попадает в числитель корректных примеров; отказ не создаёт положительного результата. Если требование труда уже превышено, действует прежний stop; если лимит достигнут и нужны дополнительные действия, удержать материал без новых затрат до решения инициатора [EXP-001] (пересмотрено по CHG-001).
Эта инструкция описывает будущий внутренний проход после C3. Локальная техническая перепроверка процедуры фиксируется отдельно в state/refusal-recovery-recheck/receipt.json; она не является результатом EXP-001/002 и не подтверждает полезность или реализуемость всего разбора в лимите [EXP-001; EXP-002] (пересмотрено по CHG-001).

'''
assert needle in s
s=s.replace(needle,block+needle)
s=s.replace('- На C3 требуется отдельное утверждение конкретной версии,', '- Проверена ветка отказа CLI: неуспех отделён от оформления, повтор от плана повтора; пропуски заполняются только по известным основаниям в общем лимите, иначе удержание и инициатор [CLM-008; CLM-009; EXP-001] (пересмотрено по CHG-001).\n- На C3 требуется отдельное утверждение конкретной версии,')
f.write_text(s)

f=p/'outputs/08_decision_log.md'; s=f.read_text()+'''
## Отказ конкретного C3 и точечная корректировка
Сценарный инициатор НЕ утвердил предъявленную версию; дословный ответ state/c3_refusal_synthetic.txt, контрольная сумма и снимок — state/c3-refused-package/manifest.json. Никакой квитанции принятия или record не было [DEC-001].
Причина — отсутствовала явная процедура восстановления после неполного входа, хотя отказ уже был наблюдён в CLM-008. Факты CLI, выбор ALT-001 и условный лимит HYP-004 не опровергнуты; новых продуктовых фактов и результатов EXP ответ не содержит [CLM-008; CLM-009; DEC-001] (пересмотрено по CHG-001).
Исправлены только инструкция внутреннему аналитику и ветка плана/EXP-001: распознавание неуспеха, сохранение входа, заполнение пропусков, повтор лишь в остатке общего лимита, удержание при неизвестности и обращение к инициатору. Технический повтор не равен полезности аудита, план не равен исполнению [EXP-001; CLM-009] (пересмотрено по CHG-001).
Старый C3 остаётся отвергнутым, исправленный пакет требует нового предъявления и отдельного ответа. C2 не переоткрывается: выбор, критерий и лимит сохранены самим сценарием; CHG-001 не закрыт [DEC-001] (пересмотрено по CHG-001).
'''; f.write_text(s)
